import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"准确率 100% 不是玄学：提取器评测怎么做","description":"","frontmatter":{"title":"准确率 100% 不是玄学：提取器评测怎么做","date":"2026-09-29T00:00:00.000Z","tags":["评测","LLM","Agent","工程实践"]},"headers":[],"relativePath":"posts/eval-extractor.md","filePath":"posts/eval-extractor.md","lastUpdated":1790688655000}'),o={name:"posts/eval-extractor.md"};function l(r,t,n,p,h,d){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="准确率-100-不是玄学-提取器评测怎么做" tabindex="-1">准确率 100% 不是玄学：提取器评测怎么做 <a class="header-anchor" href="#准确率-100-不是玄学-提取器评测怎么做" aria-label="Permalink to &quot;准确率 100% 不是玄学：提取器评测怎么做&quot;">​</a></h1><p>推广申请 Agent 的提取器，README 里写着&quot;双模式 P / R / F1 均 100%&quot;。这个数字不是拍脑袋，是 <code>tools/eval_extractor.py</code> 在真实历史确认记录上跑出来的。</p><h2 id="为什么必须评测" tabindex="-1">为什么必须评测 <a class="header-anchor" href="#为什么必须评测" aria-label="Permalink to &quot;为什么必须评测&quot;">​</a></h2><p>提取器有两套路径：<strong>规则正则</strong>（快、准、零成本）和 <strong>LLM 兜底</strong>（处理口语化文本）。问题在于——&quot;感觉准确&quot;没有任何意义。</p><ul><li>规则改一个正则，可能让 30 条历史记录集体解析失败</li><li>LLM 换模型/换 prompt，输出字段名一漂移，提取就整体失效（见《LLM 兜底为什么&quot;看似成功却返回空&quot;》）</li><li>没有基线，所有&quot;优化&quot;都是盲改</li></ul><p>评测就是把&quot;感觉&quot;变成&quot;数字&quot;。</p><h2 id="评测怎么设计" tabindex="-1">评测怎么设计 <a class="header-anchor" href="#评测怎么设计" aria-label="Permalink to &quot;评测怎么设计&quot;">​</a></h2><p><strong>数据集</strong>：真实历史确认记录（人工确认过的事实），不是自己编的样例。人工确认记录 = 权威标注，不需要另请人标数据。</p><p><strong>双模式</strong>：同一批输入，分别跑规则路径和 LLM 路径，各自算指标——这样能看出哪条路径拖后腿。</p><p><strong>指标</strong>：按提取字段逐项算 P / R / F1。</p><ul><li>Precision（精确率）：提取出来的里，多少是对的</li><li>Recall（召回率）：该提取的里，多少被提出来了</li><li>F1：两者调和平均</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/eval_extractor.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rule</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 规则模式评测</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/eval_extractor.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llm</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # LLM 模式评测</span></span></code></pre></div><p>评测报告落盘 <code>tools/eval_report.md</code>，每次改动可对比。</p><h2 id="_100-是怎么来的" tabindex="-1">100% 是怎么来的 <a class="header-anchor" href="#_100-是怎么来的" aria-label="Permalink to &quot;100% 是怎么来的&quot;">​</a></h2><p>两条路径在真实数据上分别达到 100%，靠的是：</p><ol><li><strong>规则覆盖确定性场景</strong>：金额、笔数、日期、档位这些格式固定的字段，正则比任何模型都稳</li><li><strong>LLM 只兜口语化</strong>：规则解析失败的才交给 LLM，且字段名容错映射兜住模型输出漂移</li><li><strong>评测驱动修复</strong>：先跑评测看哪里漏，再针对性改规则，而不是凭感觉调</li></ol><h2 id="收获" tabindex="-1">收获 <a class="header-anchor" href="#收获" aria-label="Permalink to &quot;收获&quot;">​</a></h2><p>&quot;准确率 100%&quot;写在 README 上是有底气的——因为它是<strong>可复现的评测结果</strong>，不是自夸。面试官问&quot;你怎么知道它准确&quot;，回答是：给我 5 分钟跑一遍 eval，数据说话。</p><blockquote><p>面试可展开：为什么不用大模型做全部提取？——评测会告诉你答案：规则路径 100% 且零成本，LLM 是兜底不是主力，这叫把确定性留给规则、把不确定性留给模型。</p></blockquote>`,19)])])}const k=a(o,[["render",l]]);export{u as __pageData,k as default};
